/* HHA chapters 4, 6, 7, 12 — infection control, home safety, emergencies, nutrition. Format: see hha-a.js */
(window.HHA = window.HHA || []).push(
{ch:4, cfr:"(b)(3)(iv)",
 title:["Kontwòl enfeksyon lakay kliyan an","Infection control in the client's home"],
 src:["S6","S1","S2","S3","S4","S11"],
 sections:[
  {h:["Poukisa sa diferan lakay moun","Why it is different in a home"],src:["S6","S1"],b:[
   ["p","Nan yon kay, pa gen yon ekip netwayaj oswa yon depo ekipman bò kote w. Ou ka vizite plizyè kliyan nan yon jou, kidonk ou ka pote mikwòb de yon kay a yon lòt si w pa fè atansyon.","In a home, there is no cleaning crew or supply room nearby. You may visit several clients in one day, so you can carry germs from one home to the next if you are not careful."],
   ["li","Pote pwòp pwovizyon ou: gan, dezenfektan men, savon, sèvyèt papye ak sak plastik.","Bring your own supplies: gloves, hand sanitizer, soap, paper towels and plastic bags."],
   ["li","Mete sak ou sou yon sifas pwòp ak sèk, pa atè ni sou kabann kliyan an.","Set your bag on a clean, dry surface, not on the floor or the client's bed."],
   ["li","Swiv plan swen an pou prekosyon espesyal kliyan an bezwen.","Follow the care plan for any special precautions the client needs."]]},
  {h:["Chèn enfeksyon an, an kout","The chain of infection, in short"],src:["S1"],b:[
   ["p","Enfeksyon pase nan sis maiyon: mikwòb la, kote l viv (rezèvwa), kote l soti, kijan l vwayaje, kote l antre, ak yon moun ki fasil pran l. Kase yon sèl maiyon, enfeksyon an rete. Maiyon ou kontwole plis la se kijan l vwayaje: men w, ekipman w ak twal yo.","Infection travels through six links: the germ, where it lives (reservoir), how it leaves, how it travels, where it enters, and a person who catches it easily. Break one link and the infection stops. The link you control most is how it travels: your hands, your equipment and linens."]]},
  {h:["Ijyèn men lakay kliyan","Hand hygiene in the home"],src:["S3"],b:[
   ["li","Netwaye men w lè w rive, anvan ak apre chak swen, anvan w prepare manje, apre w manyen fatra oswa twal sal, ak anvan w kite kay la.","Clean your hands when you arrive, before and after each care task, before preparing food, after handling trash or soiled laundry, and before you leave."],
   ["li","Sèvi ak savon ak dlo lè men w sal yon fason ou ka wè, epi lè kliyan an gen dyare (tankou C. diff). Lòt fwa, dezenfektan ki gen omwen 60% alkòl bon.","Use soap and water when your hands are visibly soiled and when the client has diarrhea (such as C. diff). Otherwise, sanitizer with at least 60% alcohol works."],
   ["li","CDC aksepte 15 a 20 segonn fwote ak savon. Pratike 20 segonn: anpil tès konpetans mande sa.","CDC accepts 15 to 20 seconds of scrubbing with soap. Practice 20 seconds, since many skills tests require it."],
   ["li","Si pa gen savon oswa sèvyèt papye nan kay la, sèvi ak pa w. Pa seche men w ak sèvyèt twal fanmi an.","If the home has no soap or paper towels, use your own. Do not dry your hands on the family's cloth towel."]]},
  {h:["Gan ak lòt PPE","Gloves and other PPE"],src:["S2","S4"],b:[
   ["p","Mete gan chak fwa w ka touche san, likid kò, po ki blese oswa bagay ki sal ak likid kò. Chanje gan ant travay sal ak travay pwòp, epi lave men w apre w retire yo.","Wear gloves any time you might touch blood, body fluids, broken skin or items soiled with body fluids. Change gloves between dirty and clean tasks, and clean your hands after you take them off."],
   ["p","Si plan swen an mande plis PPE, swiv lòd CDC a. Mete: rad izolasyon, mask, linèt, gan. Retire: gan, linèt, rad izolasyon, mask, epi ijyèn men.","If the care plan calls for more PPE, follow the CDC order. Putting on: gown, mask, goggles, gloves. Taking off: gloves, goggles, gown, mask, then hand hygiene."],
   ["li","Ofri kliyan ki touse yon mouchwa papye, epi ankouraje l kouvri bouch li. Mete yon mask si plan swen an mande l.","Offer a coughing client a tissue and encourage them to cover their mouth. Wear a mask if the care plan calls for it."]]},
  {h:["Twal sal, fatra ak zegwi","Laundry, trash and needles"],src:["S1","S11"],b:[
   ["li","Kenbe twal sal lwen inifòm ou. Pa souke yo. Mete yo dirèk nan yon sak oswa nan machin lave a.","Hold soiled linens away from your uniform. Do not shake them. Put them straight into a bag or the washer."],
   ["li","Mete fatra ki gen likid kò nan yon sak ki fèmen anvan w jete l.","Put trash with body fluids in a closed bag before throwing it out."],
   ["li","Zegwi kliyan an (tankou pou ensilin) ale dirèk nan yon bwat zegwi (sharps container). Pa janm remete kapsil sou yon zegwi.","The client's needles (for example, for insulin) go straight into a sharps container. Never recap a needle."],
   ["li","Pa ranpli bwat zegwi a plis pase anviwon twa ka, epi kenbe l lwen timoun ak bèt. Avèti sipèvizè w lè l prèske plen: yo jete l dapre règ lokal yo.","Do not fill the sharps container past about three-quarters, and keep it away from children and pets. Tell your supervisor when it is nearly full; it is disposed of by local rules."]]},
  {h:["Netwaye ak dezenfekte","Cleaning and disinfecting"],src:["S2"],b:[
   ["li","Travay depi zòn pwòp rive nan zòn sal, pou w pa pote mikwòb sou sifas ki pwòp.","Work from clean areas to dirty areas so you do not spread germs onto clean surfaces."],
   ["li","Netwaye sifas yo touche souvan: manch pòt, ba kabann, telekòmand, twalèt.","Clean surfaces people touch often: doorknobs, bed rails, remote controls, the bathroom."],
   ["li","Li etikèt dezenfektan an. Kite sifas la mouye pandan tan etikèt la mande.","Read the disinfectant label. Leave the surface wet for the time the label says."]]},
  {h:["Siy enfeksyon pou w rapòte","Signs of infection to report"],src:["S1"],b:[
   ["li","Wouj, cho, anfle, doulè, oswa likid jòn oswa vèt nan yon blesi.","Redness, warmth, swelling, pain, or yellow or green drainage from a wound."],
   ["li","Lafyèv (100.4°F oswa plis), touse ki fèk parèt, souf kout.","Fever (100.4°F or higher), a new cough, shortness of breath."],
   ["li","Pipi twoub, ak san, ak move sant, oswa ki brile.","Urine that is cloudy, bloody, foul-smelling or burning."],
   ["li","Granmoun ka pa gen lafyèv: yon konfizyon ki fèk parèt oswa yon feblès toudenkou ka sèl siy lan.","Older adults may have no fever: new confusion or sudden weakness may be the only sign."],
   ["p","Ou pa fè dyagnostik e ou pa bay medikaman. Rapòte touswit bay sipèvizè w oswa enfimyè a, epi ekri sa w wè.","You do not diagnose and you do not give medication. Report right away to your supervisor or the nurse, and write down what you saw."]]}],
 terms:[["standard precautions","prekosyon estanda"],["soiled linen","twal sal"],["sharps container","bwat zegwi"],["recap (a needle)","remete kapsil (sou zegwi)"],["disinfectant","dezenfektan"],["contact time","tan kontak"]],
 skillRefs:["handwashing"],
 qs:[
  ["hha13",0,["hand hygiene","ijyèn men"],
   ["Ou vizite twa kliyan pa jou. Ki lè ou dwe netwaye men w?","Lè w rive, anvan ak apre swen, epi anvan w kite chak kay","Sèlman lè w rive lakay premye kliyan an","Sèlman si men w sal","Sèlman nan fen jounen an","Ou se pon ant kay yo. Netwaye men w lè w rive, anvan ak apre swen, epi anvan w kite chak kay, pou mikwòb pa vwayaje avè w."],
   ["You visit three clients a day. When should you clean your hands?","When you arrive, before and after care, and before leaving each home","Only when you arrive at the first client's home","Only if your hands look dirty","Only at the end of the day","You are the link between homes. Clean your hands when you arrive, before and after care, and before leaving each home, so germs do not travel with you."]],
  ["hha14",1,["soiled linen","twal sal"],
   ["W ap chanje dra sal yon kliyan. Kijan pou w manyen yo?","Souke yo pou retire sa ki sou yo","Kenbe yo lwen inifòm ou epi pa souke yo","Kenbe yo kole sou ou pou yo pa tonbe","Mete yo atè anvan w ranmase yo","Kenbe twal sal lwen rad ou, pa souke yo paske sa voye mikwòb nan lè a, epi mete yo dirèk nan yon sak oswa nan machin lave a."],
   ["You are changing a client's soiled sheets. How should you handle them?","Shake them out to remove debris","Hold them away from your uniform and do not shake them","Hold them close so they do not fall","Put them on the floor before picking them up","Keep soiled linens away from your clothes, do not shake them because that spreads germs into the air, and put them straight into a bag or the washer."]],
  ["hha15",2,["sharps container","bwat zegwi"],
   ["Bwat zegwi (sharps container) kliyan an prèske plen a twa ka. Kisa ou fè?","Peze zegwi yo pou plis antre","Vide l nan fatra a","Pa ranpli l plis; avèti sipèvizè w pou yo ranplase l","Mete kapsil yo tounen sou zegwi yo","FDA di pa ranpli yon bwat zegwi plis pase anviwon twa ka, epi jete l dapre règ lokal yo. Pa janm remete kapsil sou yon zegwi. Avèti sipèvizè w."],
   ["The client's sharps container is about three-quarters full. What do you do?","Push the needles down to fit more","Empty it into the trash","Stop filling it and tell your supervisor so it can be replaced","Put the caps back on the needles","The FDA says not to fill a sharps container past about three-quarters, and to dispose of it by local rules. Never recap a needle. Tell your supervisor."]],
  ["hha16",0,["clean to dirty","pwòp rive nan sal"],
   ["Lè w ap netwaye twalèt kliyan an, nan ki lòd ou travay?","Depi zòn ki pi pwòp yo rive nan zòn ki pi sal yo","Depi zòn ki pi sal yo rive nan zòn ki pi pwòp yo","Nenpòt lòd","Sèlman zòn ki sanble sal","Travay depi pwòp rive nan sal pou w pa pote mikwòb sou sifas ki deja pwòp. Kite dezenfektan an rete mouye pandan tan ki ekri sou etikèt la."],
   ["When cleaning the client's bathroom, in what order do you work?","From the cleanest areas to the dirtiest","From the dirtiest areas to the cleanest","Any order","Only areas that look dirty","Work from clean to dirty so you do not spread germs onto clean surfaces. Leave the disinfectant wet for the contact time on its label."]],
  ["hha17",1,["report","rapòte"],
   ["Kliyan w lan, ki gen 80 an, konfonn depi maten epi li di li gen brili lè l ap pipi. Kisa ou fè?","Ba l ji pou l bwè epi tann demen","Rapòte sa bay sipèvizè w oswa enfimyè a touswit","Pa di anyen paske li pa gen lafyèv","Ba l yon grenn ou jwenn lakay la","Konfizyon ki fèk parèt ak brili lè l ap pipi ka siy yon enfeksyon, menm san lafyèv. Ou pa fè dyagnostik: ou rapòte touswit."],
   ["Your 80-year-old client has been confused since this morning and says it burns when she urinates. What do you do?","Give her juice and wait until tomorrow","Report it to your supervisor or the nurse right away","Say nothing because she has no fever","Give her a pill you find in the house","New confusion and burning on urination can be signs of infection, even without a fever. You do not diagnose: you report right away."]],
  ["hha8",0,["body fluids","likid kò"],
   ["Ki lè pou w mete gan ak yon kliyan?","Lè w ka touche san, likid kò oswa po ki blese","Sèlman lè kliyan an gen lafyèv","Sèlman lè w ap fè manje","Pa janm lakay moun","Mete gan chak fwa w ka touche san, pipi, poupou, vomi oswa po ki blese. Lave men w anvan ak apre."],
   ["When should you wear gloves with a client?","When you may touch blood, body fluids or broken skin","Only when the client has a fever","Only when cooking","Never in a home setting","Wear gloves any time you might touch blood, urine, stool, vomit or broken skin. Clean your hands before and after."]],
  ["h401",2,["supply bag","sak pwovizyon"],
   ["Lè w rive lakay kliyan an, ki kote pou w mete sak pwovizyon ou?","Atè bò pòt la","Sou kabann kliyan an","Sou yon sifas pwòp ak sèk","Nan twalèt la","Mete sak ou sou yon sifas pwòp ak sèk pou l pa ranmase mikwòb ou ta pote nan pwochen kay la."],
   ["When you arrive at a client's home, where should you set your supply bag?","On the floor by the door","On the client's bed","On a clean, dry surface","In the bathroom","Set your bag on a clean, dry surface so it does not pick up germs you would carry to the next home."]],
  ["h402",3,["cough etiquette","kouvri touse"],
   ["Kliyan w lan touse anpil. Ki ijyèn respiratwa ki apwopriye?","Pa okipe l","Fèmen tout fenèt","Ba l medikaman pou touse","Ofri l mouchwa papye, ankouraje l kouvri bouch li, epi mete mask si plan swen an mande l","Ijyèn respiratwa fè pati prekosyon estanda: kouvri touse, jete mouchwa, lave men, mask si plan swen an mande l."],
   ["Your client is coughing a lot. What respiratory hygiene is appropriate?","Ignore it","Close all the windows","Give cough medicine","Offer tissues, encourage covering the mouth, and wear a mask if the care plan calls for it","Respiratory hygiene is part of standard precautions: cover coughs, throw tissues away, clean hands, and mask if the care plan calls for it."]],
  ["h403", 0, ["chain of infection", "chèn enfeksyon"], ["Ki maiyon nan chèn enfeksyon an ou kontwole plis nan travay ou chak jou?", "Kijan mikwòb la vwayaje: men w, ekipman w ak twal yo", "Mikwòb la limenm", "Kote mikwòb la viv (rezèvwa)", "Fòs kò kliyan an pou l goumen ak enfeksyon", "Ou pa ka chanje mikwòb la ni kò kliyan an, men ou kontwole kijan l vwayaje. Men pwòp, ekipman pwòp ak twal ou manyen byen kase chèn nan."], ["Which link in the chain of infection can you control most in your daily work?", "How germs travel: your hands, equipment and linens", "The germ itself", "Where the germ lives (reservoir)", "The client's ability to fight infection", "You cannot change the germ or the client's body, but you control how germs travel. Clean hands, clean equipment and careful handling of linens break the chain."]],
  ["h404", 1, ["break the chain", "kase chèn nan"], ["Kisa k rive lè w kase yon sèl maiyon nan chèn enfeksyon an?", "Anyen; fòk ou kase tout sis maiyon yo", "Enfeksyon an rete, li pa gaye", "Mikwòb la vin pi fò", "Se sèlman fanmi an ki pwoteje", "Chak maiyon bezwen lòt yo. Kase yon sèl, tankou lave men w, epi enfeksyon an pa ka pase."], ["What happens when you break one link in the chain of infection?", "Nothing; you must break all six links", "The infection stops spreading", "The germ becomes stronger", "Only the family is protected", "Each link needs the others. Break just one, for example by cleaning your hands, and the infection cannot pass on."]],
  ["h405", 2, ["C. diff", "C. diff"], ["Kliyan w lan gen dyare ki soti nan C. diff. Kijan pou w netwaye men w apre swen an?", "Sèlman ak dezenfektan men ki gen alkòl", "Siye yo ak yon sèvyèt papye", "Lave yo ak savon ak dlo", "Gan yo ase; pa bezwen netwaye men w", "Lè kliyan an gen dyare tankou C. diff, oswa lè men w sal yon fason ou ka wè, lave yo ak savon ak dlo. Dezenfektan alkòl pa ase nan ka sa a."], ["Your client has diarrhea from C. diff. How should you clean your hands after care?", "With alcohol hand sanitizer only", "Wipe them on a paper towel", "Wash them with soap and water", "Gloves are enough; no need to clean your hands", "When the client has diarrhea such as C. diff, or your hands are visibly soiled, wash with soap and water. Alcohol sanitizer is not enough here."]],
  ["h406", 1, ["hand sanitizer", "dezenfektan men"], ["Dezenfektan men an dwe gen omwen konbyen alkòl?", "30%", "60%", "45%", "Nenpòt kantite", "Sèvi ak yon dezenfektan ki gen omwen 60% alkòl lè men w pa sal yon fason ou ka wè."], ["Hand sanitizer must contain at least how much alcohol?", "30%", "60%", "45%", "Any amount", "Use a sanitizer with at least 60% alcohol when your hands are not visibly soiled."]],
  ["h407", 3, ["handwashing", "lave men"], ["Lè w ap lave men w ak savon, pandan konbyen tan pou w fwote?", "5 segonn", "10 segonn", "Jiskaske dlo a vin cho", "20 segonn", "CDC aksepte 15 a 20 segonn. Pratike 20 segonn, paske anpil tès konpetans mande sa."], ["When you wash your hands with soap, how long should you scrub?", "5 seconds", "10 seconds", "Until the water gets warm", "20 seconds", "CDC accepts 15 to 20 seconds. Practice 20 seconds, since many skills tests require it."]],
  ["h408", 0, ["change gloves", "chanje gan"], ["Ou fin netwaye kliyan an apre l fè pipi sou li, epi kounye a ou bezwen ede l abiye. Kisa ou fè ak gan ou yo?", "Retire yo, netwaye men w, epi mete gan pwòp si w bezwen", "Kenbe menm gan yo pou w ale vit", "Lave gan yo ak savon epi kenbe yo", "Mete gan pwòp pa anlè gan sal yo", "Chanje gan ant yon travay sal ak yon travay pwòp, epi netwaye men w chak fwa w retire gan. Sa anpeche mikwòb pase sou rad ak sifas pwòp."], ["You finish cleaning the client after incontinence and now need to help them dress. What do you do with your gloves?", "Take them off, clean your hands, and put on clean gloves if needed", "Keep the same gloves to save time", "Wash the gloves with soap and keep them on", "Put clean gloves on over the dirty ones", "Change gloves between dirty and clean tasks, and clean your hands every time you take gloves off. This keeps germs off clean clothes and surfaces."]],
  ["h409", 2, ["removing PPE", "retire PPE"], ["Ou gen rad izolasyon, mask, linèt ak gan sou ou. Kisa pou w retire an premye?", "Mask la", "Rad izolasyon an", "Gan yo", "Linèt yo", "Dapre lòd CDC a, retire gan an premye, paske se yo ki pi sal. Apre sa linèt, rad izolasyon, mask, epi ijyèn men."], ["You are wearing a gown, mask, goggles and gloves. What do you take off first?", "The mask", "The gown", "The gloves", "The goggles", "Following the CDC order, gloves come off first because they are the most soiled. Then goggles, gown, mask, then hand hygiene."]],
  ["h410", 1, ["recap (a needle)", "remete kapsil (sou zegwi)"], ["Ou jwenn yon zegwi ensilin kliyan an te itilize sou tab la. Kisa ou fè?", "Remete kapsil la sou li epi jete l nan fatra", "Mete l dirèk nan bwat zegwi a san w pa remete kapsil", "Vlope l nan sèvyèt papye epi jete l", "Kite l sou tab la pou enfimyè a", "Pa janm remete kapsil sou yon zegwi: se konsa moun pike tèt yo. Mete l dirèk nan bwat zegwi a."], ["You find the client's used insulin needle on the table. What do you do?", "Put the cap back on and throw it in the trash", "Put it straight into the sharps container without recapping it", "Wrap it in a paper towel and throw it away", "Leave it on the table for the nurse", "Never recap a needle: that is how people stick themselves. Put it straight into the sharps container."]],
  ["h411", 3, ["wound infection", "enfeksyon blesi"], ["Pandan beny lan, ou wè blesi kliyan an wouj, cho, epi gen likid jòn-vèt k ap soti. Kisa ou fè?", "Netwaye l ak alkòl epi kouvri l", "Mete krèm antibyotik sou li", "Tann pou w wè si l ap amelyore", "Rapòte l bay enfimyè a touswit epi ekri sa w wè", "Wouj, chalè, anflamasyon ak likid jòn oswa vèt se siy enfeksyon. Ou pa trete l e ou pa bay medikaman: ou rapòte touswit epi ou ekri sa w wè."], ["During a bath, you see the client's wound is red, warm and has yellow-green drainage. What do you do?", "Clean it with alcohol and cover it", "Put antibiotic cream on it", "Wait to see if it gets better", "Report it to the nurse right away and write down what you saw", "Redness, warmth, swelling and yellow or green drainage are signs of infection. You do not treat it or give medication: you report right away and write down what you saw."]]]
},
{ch:6, cfr:"(b)(3)(vi)",
 title:["Yon kay pwòp, an sekirite ak an sante","A clean, safe and healthy home"],
 src:["S6","S1","S2","S17"],
 sections:[
  {h:["Anpeche moun tonbe","Preventing falls"],src:["S1"],b:[
   ["li","Retire tapi ki glise, fil elektrik ak bagay ki atè nan chemen yo.","Remove loose rugs, cords and clutter from walkways."],
   ["li","Bon limyè nan koridò ak eskalye, ak ti limyè lannwit ant kabann ak twalèt.","Good lighting in halls and stairs, and night lights between the bed and the bathroom."],
   ["li","Ba pou kenbe ak tapi ki pa glise nan twalèt.","Grab bars and a non-slip mat in the bathroom."],
   ["li","Mete bagay kliyan an itilize souvan nan rive men l, ansanm ak telefòn nan.","Keep things the client uses often within reach, including the phone."],
   ["li","Soulye ki pa glise. Siye dlo ak lòt bagay ki tonbe atè touswit.","Non-skid footwear. Wipe up spills right away."]]},
  {h:["Sekirite kont dife ak brili","Fire and burn safety"],src:["S1","S17"],b:[
   ["li","Detektè lafimen yo dwe mache. Rapòte si youn pa mache.","Smoke detectors must work. Report any that do not."],
   ["li","Pa gen dife, bouji ni sigarèt toupre oksijèn.","No flames, candles or cigarettes near oxygen."],
   ["li","Kenbe chofaj elektrik lwen dra, rido ak papye.","Keep space heaters away from bedding, curtains and paper."],
   ["li","Vire manch chodyè yo anndan sou recho a.","Turn pot handles inward on the stove."],
   ["li","Teste dlo beny lan anvan kliyan an antre, ak yon tèmomèt beny oswa anndan ponyèt ou. Granmoun boule fasil epi yo ka pa santi chalè byen.","Test bath water before the client gets in, with a bath thermometer or the inside of your wrist. Older adults burn easily and may not feel heat well."],
   ["li","Ti dife lwil nan yon pwela: glise yon kouvèti oswa yon plato sou li, fèmen recho a, pa deplase pwela a, epi pa janm mete dlo.","Small grease fire in a pan: slide a lid or baking sheet over it, turn off the burner, do not move the pan, and never use water."],
   ["li","Si gen dife: fè kliyan an soti, fèmen pòt yo dèyè w, epi rele 911 depi deyò.","If there is a fire: get the client out, close doors behind you, and call 911 from outside."]]},
  {h:["Pwòpte ak pwodui chimik","Cleanliness and chemicals"],src:["S2"],b:[
   ["li","Lave asyèt, siye kontwa, sòti fatra, epi tcheke frijidè a pou manje ki gate.","Wash dishes, wipe counters, take out the trash, and check the refrigerator for spoiled food."],
   ["li","Kenbe pwodui netwayaj nan bwat orijinal yo, lwen manje.","Keep cleaning products in their original containers, away from food."],
   ["li","Pa janm melanje kloròks (bleach) ak amonyak oswa ak lòt pwodui: sa fè gaz toksik.","Never mix bleach with ammonia or other cleaners: it makes toxic gas."]]},
  {h:["Sekirite pa w","Your own safety"],src:["S1"],b:[
   ["li","Konnen adrès egzak kote w ye pou w ka bay li si w rele 911.","Know the exact address where you are so you can give it if you call 911."],
   ["li","Si w santi w pa an sekirite (yon moun vyolan, yon bèt agresif, zam), kite kay la epi rele ajans ou.","If you feel unsafe (a violent person, an aggressive animal, weapons), leave and call your agency."],
   ["li","Sèvi ak bon mekanik kò lè w ap leve oswa deplase bagay.","Use good body mechanics when lifting or moving things."]]}],
 terms:[["fall prevention","prevansyon tonbe"],["grab bar","ba pou kenbe"],["non-skid footwear","soulye ki pa glise"],["smoke detector","detektè lafimen"],["space heater","chofaj elektrik"],["toxic","toksik"]],
 skills:[
  {title:["Lis sekirite lakay","Home safety checklist"],steps:[
   ["Chemen yo pwòp: pa gen tapi ki glise, fil elektrik, oswa bagay atè.","Clear paths: no loose rugs, cords, or items on the floor."],
   ["Bon limyè nan koridò ak eskalye, ak ti limyè lannwit.","Good lighting in halls and stairs, plus night lights."],
   ["Nan twalèt: ba pou kenbe ak tapi ki pa glise.","In the bathroom: grab bars and a non-slip mat."],
   ["Detektè lafimen yo mache. Pa gen dife toupre oksijèn.","Smoke detectors work. No flames near oxygen."],
   ["Pwodui netwayaj nan bwat orijinal yo, lwen manje.","Cleaning products in their original containers, away from food."],
   ["Nimewo ijans yo ak adrès kay la ekri toupre telefòn nan.","Emergency numbers and the home address are written near the phone."]],
   note:["Si w wè yon danje ou pa ka ranje, rapòte l bay sipèvizè w.","If you see a hazard you cannot fix, report it to your supervisor."]}],
 qs:[
  ["h601",3,["bleach","kloròks"],
   ["Ki melanj pwodui netwayaj ki danjere?","Savon ak dlo","Vinèg ak dlo","Dezenfektan ak dlo jan etikèt la di","Kloròks ak amonyak","Kloròks ak amonyak fè yon gaz toksik. Pa janm melanje pwodui netwayaj."],
   ["Which mix of cleaning products is dangerous?","Soap and water","Vinegar and water","Disinfectant and water as the label says","Bleach and ammonia","Bleach and ammonia make a toxic gas. Never mix cleaning products."]],
  ["h602",1,["fire","dife"],
   ["Ou wè lafimen ak dife nan kizin kliyan an. Kisa ou fè an premye?","Eseye etenn li ak dlo","Fè kliyan an soti nan kay la, fèmen pòt yo, epi rele 911 depi deyò","Rele ajans ou anvan","Ranmase papye kliyan an","Moun yo an premye: fè kliyan an soti, fèmen pòt yo pou ralanti dife a, epi rele 911 depi deyò."],
   ["You see smoke and fire in the client's kitchen. What do you do first?","Try to put it out with water","Get the client out, close doors behind you, and call 911 from outside","Call your agency first","Gather the client's papers","People first: get the client out, close doors to slow the fire, and call 911 from outside."]],
  ["h603",0,["night light","ti limyè lannwit"],
   ["Kliyan an konn leve lannwit pou l al nan twalèt. Kisa ki pi bon pou anpeche l tonbe?","Ti limyè lannwit ak yon chemen ki debarase","Fèmen pòt twalèt la","Bay kliyan an pantouf ki glise","Etenn tout limyè pou l dòmi pi byen","Ti limyè lannwit ak yon chemen san anyen atè diminye risk tonbe lannwit."],
   ["The client often gets up at night to use the bathroom. What best prevents falls?","Night lights and a clear path","Closing the bathroom door","Giving slippery slippers","Turning off all lights so they sleep better","Night lights and a clutter-free path lower the risk of falls at night."]],
  ["h604",2,["unsafe situation","sitiyasyon danjere"],
   ["Lè w rive, yon moun nan kay la sou, l ap rele epi l ap menase w. Kisa ou fè?","Rete pou w fini swen an","Diskite avè l","Kite kay la epi rele ajans ou","Fèmen tèt ou nan chanm kliyan an","Sekirite w enpòtan. Kite kay la, rele ajans ou, epi rele 911 si gen danje imedya."],
   ["When you arrive, a person in the home is drunk, shouting and threatening you. What do you do?","Stay to finish the care","Argue with them","Leave and call your agency","Lock yourself in the client's room","Your safety matters. Leave, call your agency, and call 911 if there is immediate danger."]],
  ["h605",1,["burn","boule"],
   ["W ap fè manje pou kliyan an. Kijan pou w met chodyè yo?","Ak manch yo vire deyò","Ak manch yo vire anndan sou recho a","Sou kwen recho a","Sa pa enpòtan","Manch vire anndan anpeche moun frape yo epi boule."],
   ["You are cooking for the client. How should you place the pots?","With handles turned outward","With handles turned inward on the stove","On the edge of the stove","It does not matter","Handles turned inward keep people from bumping them and getting burned."]],
  ["hha2",1,["fall prevention","prevansyon tonbe"],
   ["Ki chanjman ki fè kay yon kliyan pi an sekirite kont tonbe?","Sire planche yo","Retire tapi ki glise epi debarase chemen yo","Etenn limyè koridò a pou ekonomize","Monte kabann nan pi wo","Tapi ki glise, fil elektrik ak dezòd lakòz anpil moun tonbe. Kenbe chemen yo pwòp ak bon limyè, epi siye sa ki tonbe atè touswit."],
   ["Which change makes a client's home safest from falls?","Waxing the floors","Removing loose rugs and clearing walkways","Turning off hallway lights to save power","Raising the bed higher","Loose rugs, cords and clutter cause many falls. Keep paths clear and well lit, and wipe up spills right away."]],
  ["hha3",2,["oxygen","oksijèn"],
   ["Kliyan w lan itilize oksijèn lakay li. Ki règ ki pi enpòtan?","Mete tank lan nan solèy dirèk","Monte debi a lè l santi l fatige","Pa fimen ni pa gen dife toupre l","Kouvri tib la ak yon lenn","Oksijèn fè dife boule pi vit. Pa fimen, pa limen bouji ni dife toupre l, epi pa janm chanje debi a pou kont ou."],
   ["Your client uses oxygen at home. Which rule matters most?","Keep the tank in direct sun","Turn up the flow when they feel tired","No smoking or open flames nearby","Cover the tubing with a blanket","Oxygen makes fire burn faster. No smoking, candles or open flames near it, and never change the flow rate on your own."]],
  ["hha10",2,["burn","boule"],
   ["Anvan kliyan w lan antre nan beny lan, kijan ou tcheke dlo a?","Mande kliyan an teste l ak zòtèy li","Sèvi ak dlo ki pi cho a pou touye mikwòb","Teste l ak yon tèmomèt beny oswa anndan ponyèt ou","Kite l koule pandan yon minit","Granmoun ka boule fasil epi yo ka pa santi chalè byen. Teste dlo a anvan yo antre."],
   ["Before your client gets into the bath, how do you check the water?","Ask the client to test it with their toes","Use the hottest water to kill germs","Test it with a bath thermometer or the inside of your wrist","Let it run for one minute","Older adults burn easily and may not feel heat well. Test the water before they get in."]],
  ["h606", 1, ["grease fire", "dife grès"], ["Yon ti dife pran nan yon pwela lwil sou recho a. Kisa ki pi an sekirite?", "Voye dlo sou li", "Glise yon kouvèti oswa yon plato sou pwela a, fèmen recho a, epi pa deplase pwela a", "Pote pwela a deyò", "Vante l ak yon sèvyèt", "Pa janm mete dlo sou dife lwil. Kouvri l pou koupe lè a, fèmen recho a, epi kite kouvèti a jiskaske l frèt. Si dife a gaye, fè kliyan an soti epi rele 911 depi deyò."], ["A small fire starts in a pan of oil on the stove. What is safest?", "Throw water on it", "Slide a lid or baking sheet over the pan, turn off the burner, and do not move the pan", "Carry the pan outside", "Fan it with a towel", "Never put water on a grease fire. Cover it to cut off the air, turn off the burner, and leave the lid on until it cools. If the fire spreads, get the client out and call 911 from outside."]],
  ["h607", 0, ["within reach", "nan rive men"], ["Kliyan w lan pase pi fò jounen an nan yon fotèy. Ki kote telefòn li dwe ye?", "Nan rive men l", "Nan kizin nan pou l chaje", "Nan yon tiwa pou l pa pèdi", "Avèk moun nan fanmi an ki vin vizite", "Mete bagay kliyan an itilize souvan nan rive men l, ansanm ak telefòn nan, pou l pa oblije leve epi riske tonbe."], ["Your client spends most of the day in a recliner. Where should their phone be?", "Within their reach", "In the kitchen so it can charge", "In a drawer so it is not lost", "With the family member who visits", "Keep things the client uses often within reach, including the phone, so they do not have to get up and risk a fall."]],
  ["h608", 2, ["spill", "dlo atè"], ["Kliyan w lan jete dlo atè nan kizin nan. Kisa ou fè?", "Kite l seche poukont li", "Mete yon sèvyèt sou li epi netwaye pita", "Siye l touswit", "Di kliyan an pase bò kote l", "Siye dlo ki tonbe atè touswit. Yon planche mouye ka fè kliyan an glise epi tonbe."], ["Your client spills water on the kitchen floor. What do you do?", "Leave it to dry on its own", "Put a towel over it and clean later", "Wipe it up right away", "Tell the client to walk around it", "Wipe up spills right away. A wet floor can make the client slip and fall."]],
  ["h609", 1, ["smoke detector", "detektè lafimen"], ["Ou remake detektè lafimen nan koridò kliyan an pa mache. Kisa ou fè?", "Retire pil la nèt", "Rapòte sa bay ajans ou", "Anyen; se travay pwopriyetè a", "Tann pwochen egzèsis dife", "Detektè lafimen yo dwe mache. Rapòte si youn pa mache."], ["You notice the smoke detector in the client's hallway does not work. What do you do?", "Take the battery out for good", "Report it to your agency", "Nothing; it is the landlord's job", "Wait for the next fire drill", "Smoke detectors must work. Report any that do not."]],
  ["h610", 3, ["space heater", "chofaj elektrik"], ["Kliyan an sèvi ak yon chofaj elektrik nan chanm li. Ki kote li pi an sekirite?", "Bò kabann nan pou l rete cho", "Anba biwo a toupre papye yo", "Toupre rido yo", "Lwen dra, rido ak papye", "Kenbe chofaj elektrik lwen dra, rido ak papye, paske yo ka pran dife."], ["The client uses a space heater in the bedroom. Where is it safest?", "Next to the bed to keep them warm", "Under the desk near papers", "Close to the curtains", "Away from bedding, curtains and paper", "Keep space heaters away from bedding, curtains and paper, which can catch fire."]],
  ["h611", 0, ["original container", "bwat orijinal"], ["Ou vle vide kloròks nan yon boutèy ji vid pou l pi fasil pou sèvi. Kisa ki kòrèk?", "Kenbe pwodui netwayaj nan bwat orijinal yo, lwen manje", "Sa bon si w mete yon etikèt sou boutèy la", "Sa bon si w rense boutèy la anvan", "Sa bon si w mete l nan frijidè a", "Kenbe pwodui netwayaj nan bwat orijinal yo, lwen manje, pou pesonn pa bwè yo oswa melanje yo pa erè."], ["You want to pour bleach into an empty juice bottle so it is easier to use. What is correct?", "Keep cleaning products in their original containers, away from food", "It is fine if you label the bottle", "It is fine if you rinse the bottle first", "It is fine if you keep it in the refrigerator", "Keep cleaning products in their original containers and away from food, so no one drinks or mixes them by mistake."]],
  ["h612", 2, ["address", "adrès"], ["Poukisa ou dwe konnen adrès egzak kay kote w ap travay la?", "Pou w ranpli fèy lè travay ou", "Pou w di zanmi w kote w ye", "Pou w ka bay li a 911 si gen yon ijans", "Pou w voye lèt bay kliyan an", "Konnen adrès egzak kote w ye pou w ka bay li si w rele 911."], ["Why should you know the exact address of the home where you are working?", "To fill out your timesheet", "To tell your friends where you are", "To give it to 911 in an emergency", "To mail the client letters", "Know the exact address where you are so you can give it if you call 911."]]]
},
{ch:7, cfr:"(b)(3)(vii)",
 title:["Rekonèt ijans epi aji","Recognizing and handling emergencies"],
 src:["S6","S13","S14","S1"],
 sections:[
  {h:["Premye etap yo","First steps"],src:["S1"],b:[
   ["n","Rete kalm epi asire w kote a san danje pou ou ak kliyan an.","Stay calm and make sure the scene is safe for you and the client."],
   ["n","Pou yon ijans ki menase lavi, rele 911 an premye. Bay adrès egzak la, sa k pase, ak kondisyon kliyan an. Rete sou liy lan.","For a life-threatening emergency, call 911 first. Give the exact address, what happened, and the client's condition. Stay on the line."],
   ["n","Pa kite kliyan an poukont li.","Do not leave the client alone."],
   ["n","Rele ajans ou osito w kapab, epi ekri sa k te pase.","Call your agency as soon as you can, and write down what happened."],
   ["p","Ajans ou gen yon plan pou ijans. Konnen sa plan swen kliyan an di pou ijans.","Your agency has an emergency plan. Know what the client's care plan says about emergencies."]]},
  {h:["Toufe","Choking"],src:["S14"],b:[
   ["li","Siy: moun nan kenbe gòj li, li pa ka pale, li respire ak bri, touse fèb, oswa po l vin ble.","Signs: the person grabs their throat, cannot speak, breathes noisily, coughs weakly, or turns blue."],
   ["li","Mande: «W ap toufe? Ou ka pale?» Si l ka touse fò oswa pale, ankouraje l kontinye touse.","Ask: “Are you choking? Can you speak?” If they can cough hard or speak, encourage them to keep coughing."],
   ["li","Si l pa ka pale ni respire byen, epi ou fòme pou sa: 5 kou nan do ant zo zepòl yo, epi 5 pouse nan vant (Heimlich). Kontinye jiskaske bagay la soti.","If they cannot speak or breathe well and you are trained: 5 back blows between the shoulder blades, then 5 abdominal thrusts (Heimlich). Repeat until the object comes out."],
   ["li","Si l pèdi konesans: rele 911, kouche l sou yon sifas plat, epi kòmanse CPR si w fòme.","If they become unconscious: call 911, lay them on a flat surface, and start CPR if you are trained."]]},
  {h:["Estwòk: B.E. F.A.S.T.","Stroke: B.E. F.A.S.T."],src:["S13"],b:[
   ["li","B (Balans): li toudi oswa li pèdi balans?","B (Balance): are they dizzy or off balance?"],
   ["li","E (Je): li gen pwoblèm pou l wè?","E (Eyes): do they have trouble seeing?"],
   ["li","F (Figi): mande l souri. Èske yon bò figi a tonbe?","F (Face): ask them to smile. Does one side droop?"],
   ["li","A (Bra): mande l leve de bra yo. Èske youn desann?","A (Arms): ask them to raise both arms. Does one drift down?"],
   ["li","S (Pawòl): mande l repete yon fraz. Èske pawòl yo melanje oswa dwòl?","S (Speech): ask them to repeat a phrase. Is it slurred or strange?"],
   ["li","T (Tan): rele 911 touswit epi note ki lè siy yo te kòmanse.","T (Time): call 911 right away and note when the signs started."]]},
  {h:["Lòt ijans","Other emergencies"],src:["S1","S13"],b:[
   ["li","Kriz kadyak: doulè oswa presyon nan pwatrin, doulè nan bra, machwè oswa do, souf kout, swe frèt, kè plen. Rele 911.","Heart attack: chest pain or pressure, pain in the arm, jaw or back, shortness of breath, cold sweat, nausea. Call 911."],
   ["li","Tonbe: pa leve kliyan an poukont ou. Gade si l blese, rele enfimyè a oswa 911 si l blese, kenbe l cho ak konfòtab, epi rapòte tonbe a menm si l pa blese.","Fall: do not lift the client by yourself. Check for injury, call the nurse or 911 if injured, keep them warm and comfortable, and report the fall even with no injury."],
   ["li","Kriz (seizure): pwoteje tèt li, retire bagay ki ka blese l, pa kenbe l fò, pa mete anyen nan bouch li, epi gade lè a. Apre sa, vire l sou kote. Rele 911 si kriz la dire plis pase 5 minit.","Seizure: protect their head, move objects away, do not hold them down, put nothing in their mouth, and time it. Afterward, turn them on their side. Call 911 if it lasts more than 5 minutes."],
   ["li","Sik ba (dyabèt): tranble, swe, konfizyon, kè bat vit. Swiv plan swen an epi rapòte; rele 911 si l pa reponn.","Low blood sugar (diabetes): shaky, sweaty, confused, fast heartbeat. Follow the care plan and report; call 911 if they do not respond."],
   ["li","San k ap koule: mete gan, peze dirèkteman sou blesi a ak yon twal pwòp.","Bleeding: put on gloves and press directly on the wound with a clean cloth."],
   ["li","Brili: mete l anba dlo frèt k ap koule (pa glas), epi rapòte l.","Burns: cool under running cool water (not ice), and report it."]]}],
 terms:[["emergency","ijans"],["choking","toufe"],["abdominal thrusts","pouse nan vant (Heimlich)"],["stroke","estwòk"],["seizure","kriz (malkadi)"],["low blood sugar","sik ba"],["unconscious","pèdi konesans"]],
 skills:[
  {title:["Repons pou yon moun k ap toufe","Responding to choking"],steps:[
   ["Mande: «W ap toufe? Ou ka pale?»","Ask: “Are you choking? Can you speak?”"],
   ["Si l ka touse fò, ankouraje l kontinye touse. Rete avè l.","If they can cough hard, encourage them to keep coughing. Stay with them."],
   ["Si l pa ka pale ni respire, rele pou èd epi fè yon moun rele 911.","If they cannot speak or breathe, shout for help and have someone call 911."],
   ["Si w fòme: 5 kou nan do ant zo zepòl yo, apre sa 5 pouse nan vant, anwo lonbrit la.","If trained: 5 back blows between the shoulder blades, then 5 abdominal thrusts just above the navel."],
   ["Si l pèdi konesans: kouche l atè, rele 911, epi kòmanse CPR si w fòme.","If they become unconscious: lower them to the floor, call 911, and start CPR if trained."]],
   note:["Menm si bagay la soti, moun nan dwe wè yon pwofesyonèl sante. Rapòte l bay ajans ou.","Even if the object comes out, the person should see a health care provider. Report it to your agency."]},
  {title:["Rele 911","Calling 911"],steps:[
   ["Di adrès egzak la, ak apatman oswa etaj la.","Give the exact address, including the apartment or floor."],
   ["Di sa k pase ak kondisyon kliyan an kounye a.","Say what happened and the client's condition right now."],
   ["Bay non w epi di w se ed swen a domisil.","Give your name and say you are a home health aide."],
   ["Reponn kesyon yo epi swiv enstriksyon yo. Pa rakwoche anvan yo di w.","Answer their questions and follow their instructions. Do not hang up until they tell you."],
   ["Apre sa, rele ajans ou epi ekri sa k te pase ak lè a.","Afterward, call your agency and write down what happened and when."]],
   note:["Kenbe adrès kliyan an sou ou chak vizit.","Keep the client's address with you at every visit."]}],
 qs:[
  ["h701",1,["choking","toufe"],
   ["Kliyan an kòmanse touse fò pandan l ap manje, men li ka pale. Kisa ou fè?","Fè pouse nan vant touswit","Ankouraje l kontinye touse epi rete avè l","Ba l dlo pou l bwè vit","Frape do l fò touswit","Si moun nan ka touse fò oswa pale, pa entèvni. Ankouraje l touse; yon touse fò ka fè bagay la soti."],
   ["The client starts coughing hard while eating but can speak. What do you do?","Give abdominal thrusts right away","Encourage them to keep coughing and stay with them","Give water to drink quickly","Hit their back hard right away","If the person can cough hard or speak, do not intervene. Encourage coughing; a strong cough can clear the object."]],
  ["h702",2,["stroke","estwòk"],
   ["Kliyan an souri epi yon bò figi l tonbe, epi pawòl li melanje. Kisa ou fè?","Fè l kouche pou l repoze","Ba l yon aspirin","Rele 911 touswit epi note ki lè siy yo te kòmanse","Tann pou wè si sa pase","Figi ki tonbe ak pawòl melanje se siy estwòk. Rele 911 touswit epi note lè a: tretman depann de tan an."],
   ["The client smiles and one side of the face droops, and the speech is slurred. What do you do?","Have them lie down to rest","Give an aspirin","Call 911 right away and note when the signs started","Wait to see if it passes","A drooping face and slurred speech are stroke signs. Call 911 right away and note the time: treatment depends on it."]],
  ["h703",3,["seizure","kriz"],
   ["Kliyan an gen yon kriz (seizure). Kisa ou pa dwe fè?","Pwoteje tèt li","Retire bagay ki bò kote l","Gade konbyen tan l dire","Mete yon bagay nan bouch li","Pa mete anyen nan bouch yon moun k ap fè kriz. Pwoteje tèt li, retire bagay danjere, epi gade lè a."],
   ["The client is having a seizure. What should you NOT do?","Protect their head","Move objects away from them","Time how long it lasts","Put something in their mouth","Never put anything in the mouth of a person having a seizure. Protect the head, clear the area, and time it."]],
  ["h704",0,["fall","tonbe"],
   ["Ou jwenn kliyan an atè. Li di li byen. Kisa ou fè?","Pa leve l poukont ou; gade si l blese, rele enfimyè a oswa ajans ou, epi rapòte tonbe a","Leve l vit epi pa di anyen","Kite l atè jiskaske fanmi an rive","Ba l yon grenn pou doulè","Pa leve yon kliyan poukont ou apre yon tonbe. Gade si l blese, rele pou èd, epi rapòte chak tonbe."],
   ["You find the client on the floor. They say they are fine. What do you do?","Do not lift them alone; check for injury, call the nurse or agency, and report the fall","Lift them quickly and say nothing","Leave them on the floor until the family arrives","Give a pain pill","Do not lift a client alone after a fall. Check for injury, call for help, and report every fall."]],
  ["h705",1,["heart attack","kriz kadyak"],
   ["Ki siy sa yo ka montre yon kriz kadyak?","Grangou ak swaf","Doulè nan pwatrin, souf kout ak swe frèt","Grate nan po","Dòmi twòp","Doulè oswa presyon nan pwatrin, souf kout, swe frèt ak kè plen ka siy kriz kadyak. Rele 911."],
   ["Which signs can mean a heart attack?","Hunger and thirst","Chest pain, shortness of breath and cold sweat","Itchy skin","Sleeping too much","Chest pain or pressure, shortness of breath, cold sweat and nausea can be heart attack signs. Call 911."]],
  ["h706",2,["burn","boule"],
   ["Kliyan an boule men l ak dlo cho. Ki premye swen an?","Mete glas sou li","Mete bè oswa lwil sou li","Mete l anba dlo frèt k ap koule, epi rapòte l","Pete anpoul yo","Refwadi yon brili anba dlo frèt k ap koule. Pa mete glas, bè oswa lwil, epi pa pete anpoul yo."],
   ["The client burns a hand with hot water. What is the first care?","Put ice on it","Put butter or oil on it","Cool it under running cool water, and report it","Pop the blisters","Cool a burn under running cool water. Do not use ice, butter or oil, and do not pop blisters."]],
  ["h707",0,["bleeding","senyen"],
   ["Kliyan an koupe dwèt li epi l ap senyen. Kisa ou fè?","Mete gan epi peze dirèkteman sou blesi a ak yon twal pwòp","Lave l ak alkòl san gan","Kite l senyen pou l netwaye","Mete yon gawo tou swit","Pwoteje tèt ou ak gan, epi peze dirèkteman sou blesi a. Rapòte l; rele 911 si l pa sispann."],
   ["The client cuts a finger and it is bleeding. What do you do?","Put on gloves and press directly on the wound with a clean cloth","Wash it with alcohol without gloves","Let it bleed to clean it","Apply a tourniquet right away","Protect yourself with gloves, and press directly on the wound. Report it; call 911 if it does not stop."]],
  ["hha5",1,["emergency","ijans"],
   ["Kliyan w lan pa reponn epi li pa respire nòmalman. Kisa ou fè an premye?","Rele fanmi kliyan an","Rele 911 epi swiv fòmasyon ijans ou","Ba l dlo","Tann 10 minit pou wè si sa pase","Rele 911 touswit. Kòmanse CPR si w fòme pou sa, epi avèti ajans ou."],
   ["Your client does not respond and is not breathing normally. What do you do first?","Call the client's family","Call 911 and follow your emergency training","Give them water","Wait 10 minutes to see if it passes","Call 911 right away. Start CPR if you are trained, then notify your agency."]],
  ["h708", 1, ["911 call", "rele 911"], ["Ou rele 911 paske kliyan w lan tonbe san konesans. Kisa pou w fè pandan apèl la?", "Rakwoche vit pou yo vin pi vit", "Bay adrès egzak la, sa k pase ak kondisyon kliyan an, epi rete sou liy lan", "Kite kliyan an pou w al tann anbilans lan deyò", "Rele ajans ou an premye, apre sa 911", "Bay adrès egzak la, sa k pase ak kondisyon kliyan an, epi rete sou liy lan. Pa kite kliyan an poukont li. Rele ajans ou osito w kapab."], ["You call 911 because your client collapsed. What should you do on the call?", "Hang up quickly so they come faster", "Give the exact address, what happened and the client's condition, and stay on the line", "Leave the client to wait outside for the ambulance", "Call your agency first, then 911", "Give the exact address, what happened and the client's condition, and stay on the line. Do not leave the client alone. Call your agency as soon as you can."]],
  ["h709", 3, ["unconscious", "pèdi konesans"], ["Kliyan w lan t ap toufe epi kounye a li pèdi konesans. Kisa ou fè?", "Kontinye frape do l pandan l chita nan chèz la", "Ba l dlo pou manje a desann", "Fè l chita epi tann li reveye", "Rele 911, kouche l sou yon sifas plat, epi kòmanse CPR si w fòme", "Si moun ki t ap toufe a pèdi konesans: rele 911, kouche l sou yon sifas plat, epi kòmanse CPR si w fòme."], ["Your client was choking and now becomes unconscious. What do you do?", "Keep hitting their back while they sit in the chair", "Give them water to wash the food down", "Sit them up and wait for them to wake", "Call 911, lay them on a flat surface, and start CPR if you are trained", "If a choking person becomes unconscious: call 911, lay them on a flat surface, and start CPR if you are trained."]],
  ["h710", 0, ["seizure", "kriz"], ["Kriz kliyan w lan dire plis pase 5 minit. Kisa ou fè?", "Rele 911", "Kenbe l fò jiskaske l rete", "Mete yon kiyè nan bouch li", "Tann; kriz toujou rete poukont yo", "Rele 911 si yon kriz dire plis pase 5 minit. Se pou sa ou gade lè a pandan chak kriz."], ["Your client's seizure has lasted more than 5 minutes. What do you do?", "Call 911", "Hold them down until it stops", "Put a spoon in their mouth", "Wait; seizures always stop on their own", "Call 911 if a seizure lasts more than 5 minutes. That is why you time every seizure."]],
  ["h711", 2, ["recovery position", "pozisyon sou kote"], ["Kriz kliyan w lan fèk fini. Ki pozisyon pou w mete l?", "Fè l chita touswit", "Kouche plat sou do", "Sou kote", "Kanpe, pou l mache", "Apre yon kriz, vire moun nan sou kote l."], ["Your client's seizure has just ended. How should you position them?", "Sit them up right away", "Flat on their back", "On their side", "Standing, so they can walk it off", "After a seizure, turn the person onto their side."]],
  ["h712", 1, ["low blood sugar", "sik ba"], ["Kliyan w lan ki gen dyabèt toudenkou ap tranble, l ap swe, li konfonn, epi kè l ap bat vit. Kisa sa ka ye?", "Fatig nòmal", "Sik ba; swiv plan swen an epi rapòte l", "Yon grip k ap vini", "Twòp dlo", "Tranble, swe, konfizyon ak kè ki bat vit ka vle di sik ba. Swiv plan swen an, rapòte l, epi rele 911 si l pa reponn."], ["Your client with diabetes is suddenly shaky, sweaty and confused, with a fast heartbeat. What may this be?", "Normal tiredness", "Low blood sugar; follow the care plan and report it", "A cold coming on", "Too much water", "Shaking, sweating, confusion and a fast heartbeat can mean low blood sugar. Follow the care plan, report it, and call 911 if they do not respond."]]]
},
{ch:12, cfr:"(b)(3)(xii)",
 title:["Manje ak likid","Nutrition and fluid intake"],
 src:["S6","S1","S15"],
 sections:[
  {h:["Yon bon alimantasyon","Good nutrition"],src:["S1"],b:[
   ["p","Yon kò ki byen nouri pi fò, li geri pi byen, epi li reziste enfeksyon. Swiv rejim espesyal ki nan plan swen an chak fwa.","A well-nourished body is stronger, heals better and fights infection. Follow any special diet in the care plan every time."],
   ["li","Mwens sèl (low sodium): pou tansyon wo oswa pwoblèm kè. Chwazi manje fre (vyann fre, legim); evite soup an bwat, vyann trete, nouy enstantane ak chips.","Low sodium: for high blood pressure or heart problems. Choose fresh foods (fresh meat, vegetables); avoid canned soups, processed meats, instant noodles and chips."],
   ["li","Rejim pou dyabèt: kontwole sik ak kantite karbonidrat.","Diabetic diet: controls sugar and carbohydrates."],
   ["li","Manje mou oswa moulen (mechanical soft, puree): pou moun ki gen pwoblèm pou kraze oswa vale.","Soft or pureed food (mechanical soft, puree): for people with chewing or swallowing problems."],
   ["li","Likid epè (thickened liquids): pou moun ki gen pwoblèm pou vale. Swiv konsistans lan egzakteman: likid ki pa epè ase ka antre nan poumon.","Thickened liquids: for people with swallowing problems. Follow the thickness exactly: liquid that is too thin can go into the lungs."]]},
  {h:["Likid ak dezidratasyon","Fluids and dehydration"],src:["S1"],b:[
   ["li","Ankouraje likid pandan jounen an, sòf si plan swen an limite yo.","Encourage fluids throughout the day, unless the care plan limits them."],
   ["li","Si gen restriksyon likid, swiv li egzakteman epi mezire sa kliyan an bwè si yo mande w.","If fluids are restricted, follow it exactly and measure intake if asked."],
   ["li","Si yon kliyan ki gen restriksyon likid swaf, ofri l swen bouch oswa krèm pou po bouch. Bay ti mòso glas sèlman si plan swen an pèmèt sa: yo konte kòm likid. Rapòte swaf la bay enfimyè a.","If a client on a fluid restriction is thirsty, offer mouth care or lip moisturizer. Give ice chips only if the care plan allows: they count as fluid. Report the thirst to the nurse."],
   ["li","Siy dezidratasyon: bouch sèk, pipi fonse oswa pi piti pipi, tèt vire, konfizyon. Rapòte yo.","Signs of dehydration: dry mouth, dark urine or less urine, dizziness, confusion. Report them."]]},
  {h:["Ede kliyan an manje","Helping the client eat"],src:["S1"],b:[
   ["li","Fè kliyan an chita dwat, toupre 90 degre si l kapab, pou l manje, epi rete chita kèk tan apre.","Sit the client upright, as close to 90 degrees as they can, to eat, and keep them upright for a while after."],
   ["li","Ti mòso, epi kite l kraze ak vale anvan pwochen mòso a. Pa prese l.","Small bites, and let them chew and swallow before the next bite. Do not rush."],
   ["li","Gade si manje rete nan bouch li (anndan machwè). Fè l sonje kraze ak vale, epi rapòte l.","Check for food held in the cheeks (pocketing). Remind them to chew and swallow, and report it."],
   ["li","Ankouraje l manje poukont li otan l kapab.","Encourage them to feed themselves as much as they can."],
   ["li","Ekri konbyen l manje (egzanp: 50%) ak konbyen l bwè si yo mande w.","Record how much they ate (for example, 50%) and drank if asked."],
   ["li","Rapòte touse oswa toufe pandan manje.","Report coughing or choking during meals."]]},
  {h:["Sekirite manje","Food safety"],src:["S15","S19"],b:[
   ["li","Frijidè a dwe nan 40°F (4°C) oswa pi ba. Frizè a nan 0°F (-18°C) oswa pi ba.","Keep the refrigerator at 40°F (4°C) or below and the freezer at 0°F (-18°C) or below."],
   ["li","Rès vyann oswa poul kwit: 3 a 4 jou nan frijidè.","Leftover cooked meat or poultry: 3 to 4 days in the refrigerator."],
   ["li","Mete manje ki rete nan frijidè anvan 2 èdtan apre w fin kwit li (anvan 1 èdtan si fè plis pase 90°F). Jete manje ki rete deyò pi lontan pase sa.","Refrigerate leftovers within 2 hours of cooking (within 1 hour if it is above 90°F). Throw out food left out longer."],
   ["li","Lave men w anvan w prepare manje, epi jete manje ki gate.","Clean your hands before preparing food, and throw out spoiled food."]]},
  {h:["Chwa kliyan an","The client's choices"],src:["S1"],b:[
   ["p","Kliyan an ka refize manje. Pwopoze yon lòt chwa ki nan rejim li, respekte desizyon l, note konbyen l manje, epi rapòte si sa kontinye.","The client may refuse food. Offer another choice within their diet, respect the decision, note how much they ate, and report if it continues."]]}],
 terms:[["special diet","rejim espesyal"],["low sodium","mwens sèl"],["thickened liquids","likid epè"],["fluid restriction","restriksyon likid"],["dehydration","dezidratasyon"],["intake","sa kliyan an manje ak bwè"],["pocketing food","kenbe manje nan machwè"]],
 qs:[
  ["h1201",2,["thickened liquids","likid epè"],
   ["Plan swen an di kliyan an bezwen likid epè. Li mande yon vè dlo nòmal. Kisa ou fè?","Ba l dlo nòmal paske l mande l","Ba l mwatye vè dlo nòmal","Ba l likid la nan konsistans plan swen an mande, epi eksplike poukisa","Pa ba l anyen pou bwè","Likid ki pa epè ase ka antre nan poumon moun ki gen pwoblèm pou vale. Swiv konsistans lan egzakteman."],
   ["The care plan says the client needs thickened liquids. They ask for a glass of plain water. What do you do?","Give plain water because they asked","Give half a glass of plain water","Give the liquid at the thickness the care plan requires, and explain why","Give nothing to drink","Thin liquid can go into the lungs of someone with swallowing problems. Follow the thickness exactly."]],
  ["h1202",1,["dehydration","dezidratasyon"],
   ["Ki siy sa yo ka montre dezidratasyon?","Pipi klè an kantite","Bouch sèk ak pipi fonse","Pye anfle","Twòp grangou","Bouch sèk, pipi fonse oswa pi piti pipi, tèt vire ak konfizyon ka siy dezidratasyon. Rapòte yo."],
   ["Which signs can mean dehydration?","Lots of clear urine","Dry mouth and dark urine","Swollen feet","Too much hunger","Dry mouth, dark or less urine, dizziness and confusion can be signs of dehydration. Report them."]],
  ["h1203",0,["refrigerator temperature","tanperati frijidè"],
   ["Ki tanperati frijidè kliyan an dwe genyen?","40°F (4°C) oswa pi ba","50°F (10°C)","60°F (16°C)","Nenpòt tanperati si l frèt","Frijidè a dwe rete nan 40°F (4°C) oswa pi ba pou anpeche mikwòb grandi."],
   ["What temperature should the client's refrigerator be?","40°F (4°C) or below","50°F (10°C)","60°F (16°C)","Any temperature if it feels cold","Keep the refrigerator at 40°F (4°C) or below to slow germ growth."]],
  ["h1204",3,["leftovers","rès manje"],
   ["Konbyen tan rès poul kwit ka rete nan frijidè?","1 semèn","2 semèn","1 mwa","3 a 4 jou","Rès vyann ak poul kwit bon pou 3 a 4 jou nan frijidè."],
   ["How long can leftover cooked chicken stay in the refrigerator?","1 week","2 weeks","1 month","3 to 4 days","Leftover cooked meat and poultry keep 3 to 4 days in the refrigerator."]],
  ["h1205",1,["fluid restriction","restriksyon likid"],
   ["Kliyan an gen restriksyon likid epi l mande plis dlo pase sa plan an pèmèt. Kisa ou fè?","Ba l kantite l mande a","Pa ba l plis pase sa plan an pèmèt, ofri l lòt fason pou soulaje swaf, epi di enfimyè a","Kache dlo a","Di l li pa ka bwè ankò jodi a san eksplike","Swiv restriksyon an egzakteman. Ofri swen bouch; bay ti mòso glas sèlman si plan swen an pèmèt sa, paske yo konte kòm likid. Rapòte swaf la."],
   ["The client is on a fluid restriction and asks for more water than the plan allows. What do you do?","Give what they ask for","Do not give more than the plan allows, offer other comfort for thirst, and tell the nurse","Hide the water","Tell them no more today without explaining","Follow the restriction exactly. Offer mouth care; give ice chips only if the care plan allows, since they count as fluid. Report the thirst."]],
  ["h1206",2,["pocketing food","kenbe manje nan machwè"],
   ["Pandan manje, ou remake kliyan an kenbe manje nan machwè l. Kisa ou fè?","Ba l plis manje vit","Kouche l","Fè l sonje kraze ak vale, tcheke bouch li, epi rapòte l","Pa okipe l","Kenbe manje nan machwè ka siy pwoblèm pou vale epi l ka lakòz toufe. Fè l sonje vale, tcheke bouch li, epi rapòte."],
   ["During a meal, you notice the client holding food in their cheeks. What do you do?","Give more food quickly","Lay them down","Remind them to chew and swallow, check their mouth, and report it","Ignore it","Pocketing food can signal a swallowing problem and cause choking. Remind them to swallow, check the mouth, and report it."]],
  ["hha4",0,["food safety","sekirite manje"],
   ["Manje kwit ki rete dwe antre nan frijidè nan konbyen tan?","Anvan 2 èdtan","Anvan 6 èdtan","Denmen maten","Sèlman si l gen move sant","Mikwòb grandi vit nan tanperati chanm. Mete manje kwit nan frijidè anvan 2 èdtan (1 èdtan si fè plis pase 90°F deyò)."],
   ["Leftover cooked food should go in the refrigerator within how long?","Within 2 hours","Within 6 hours","By the next morning","Only if it smells bad","Bacteria grow fast at room temperature. Refrigerate cooked food within 2 hours (1 hour if it is above 90°F outside)."]],
  ["hha12",0,["refuse","refize"],
   ["Kliyan w lan refize manje manje midi. Ki pi bon repons lan?","Pwopoze yon lòt chwa, respekte desizyon l, epi rapòte sa","Fòse l manje","Retire manje aswè a tou","Di l li difisil","Kliyan yo ka refize. Pwopoze lòt chwa, note konbyen l manje, epi di sipèvizè w si sa kontinye rive."],
   ["Your client refuses to eat lunch. What is the best response?","Offer another choice, respect the decision, and report it","Feed them anyway","Take away dinner too","Tell them they are being difficult","Clients can refuse. Offer alternatives, note how much they ate, and tell your supervisor if it keeps happening."]],
  ["h1207", 0, ["low sodium", "mwens sèl"], ["Kliyan an sou yon rejim ki gen mwens sèl. Ki repa ki pi bon?", "Poul fre griye ak bwokoli bouyi san sèl ajoute", "Soup an bwat ak krakè sale", "Janbon ak fwomaj tranche", "Nouy enstantane ak sachè epis", "Manje fre gen mwens sèl pase manje an bwat, vyann trete ak nouy enstantane. Swiv rejim ki nan plan swen an."], ["The client is on a low-sodium diet. Which meal is best?", "Fresh grilled chicken with steamed broccoli, no added salt", "Canned soup with salted crackers", "Deli ham and sliced cheese", "Instant noodles with the seasoning packet", "Fresh foods have far less sodium than canned soups, processed meats and instant noodles. Follow the diet in the care plan."]],
  ["h1208", 1, ["diabetic diet", "rejim pou dyabèt"], ["Kisa yon rejim pou dyabèt kontwole?", "Sèl sèlman", "Sik ak karbonidrat", "Likid sèlman", "Pwoteyin sèlman", "Yon rejim pou dyabèt kontwole sik ak kantite karbonidrat. Swiv rejim espesyal ki nan plan swen an chak fwa."], ["What does a diabetic diet control?", "Salt only", "Sugar and carbohydrates", "Fluids only", "Protein only", "A diabetic diet controls sugar and carbohydrates. Follow any special diet in the care plan every time."]],
  ["h1209", 2, ["pureed diet", "manje moulen"], ["Ki moun ki konn bezwen manje mou oswa moulen?", "Moun ki sou rejim mwens sèl", "Moun ki grangou anpil", "Moun ki gen pwoblèm pou kraze oswa vale", "Moun ki pa renmen legim", "Manje mou oswa moulen (mechanical soft, puree) se pou moun ki gen pwoblèm pou kraze oswa vale."], ["Who usually needs soft or pureed food?", "People on a low-sodium diet", "People who are very hungry", "People with chewing or swallowing problems", "People who do not like vegetables", "Soft or pureed food (mechanical soft, puree) is for people with chewing or swallowing problems."]],
  ["h1210", 0, ["upright position", "chita dwat"], ["Kliyan w lan fèk fin manje midi. Kisa l dwe fè apre?", "Rete chita dwat pandan yon ti tan", "Kouche plat touswit pou l repoze", "Kouche sou vant", "Panche pou l touche zòtèy li", "Fè kliyan an chita dwat pou l manje, epi rete chita kèk tan apre."], ["Your client just finished lunch. What should they do next?", "Stay sitting upright for a while", "Lie flat right away to rest", "Lie on their stomach", "Bend forward to touch their toes", "Sit the client upright to eat, and keep them upright for a while after."]],
  ["h1211", 3, ["coughing during meals", "touse pandan manje"], ["Kliyan w lan touse chak fwa l bwè pandan manje. Kisa ou fè?", "Ba l pi gwo gòje pou l desann pi vit", "Fè l kouche", "Sispann ba l bwè pou rès jounen an", "Rapòte sa bay enfimyè a", "Rapòte touse oswa toufe pandan manje. Sa ka siy yon pwoblèm pou vale."], ["Your client coughs every time they drink during meals. What do you do?", "Give bigger sips so it goes down faster", "Have them lie down", "Stop giving drinks for the rest of the day", "Report it to the nurse", "Report coughing or choking during meals. It can be a sign of a swallowing problem."]],
  ["h1212", 1, ["self-feeding", "manje poukont li"], ["Kliyan w lan ka manje poukont li men li dousman. Kisa ki pi bon?", "Ba l manje nan bouch pou manje a ale pi vit", "Ankouraje l manje poukont li epi pa prese l", "Retire asyèt la apre 10 minit", "Moulen tout manje a pou l ale pi vit", "Ankouraje kliyan an manje poukont li otan l kapab, epi pa prese l. Ti mòso, epi kite l kraze ak vale anvan pwochen mòso a."], ["Your client can feed themselves but is slow. What is best?", "Feed them so the meal goes faster", "Encourage them to feed themselves and do not rush them", "Take the plate away after 10 minutes", "Blend all the food so it goes faster", "Encourage the client to feed themselves as much as they can, and do not rush. Small bites, and let them chew and swallow before the next one."]]]
}
);
